// Two binaries, one source. The slot letter and the version are the only
// difference between the A image and the B image, so they are build inputs, not
// edits: run.sh sets EXP142_SLOT and EXP142_VERSION and builds twice.
//
// A generated file, rather than a `-D` define, so the values are real consts the
// IMAGE_DEF's VERSION word can be built from at compile time.
use std::{env, fs, path::PathBuf};

fn main() {
    let slot = env::var("EXP142_SLOT").unwrap_or_else(|_| "A".to_string());
    // Version as major.minor; the ROM compares these across the A/B pair and
    // boots the higher. Default 1.0 so a plain `cargo build` still produces a
    // valid, bootable image.
    let major: u16 = env::var("EXP142_MAJOR").ok().and_then(|v| v.parse().ok()).unwrap_or(1);
    let minor: u16 = env::var("EXP142_MINOR").ok().and_then(|v| v.parse().ok()).unwrap_or(0);

    let out = PathBuf::from(env::var_os("OUT_DIR").unwrap());
    let body = format!(
        "// generated by build.rs — do not edit\n\
         pub const SLOT: &str = {slot:?};\n\
         pub const VERSION_MAJOR: u16 = {major};\n\
         pub const VERSION_MINOR: u16 = {minor};\n"
    );
    fs::write(out.join("exp142_config.rs"), body).unwrap();

    println!("cargo:rerun-if-env-changed=EXP142_SLOT");
    println!("cargo:rerun-if-env-changed=EXP142_MAJOR");
    println!("cargo:rerun-if-env-changed=EXP142_MINOR");
    println!("cargo:rerun-if-changed=build.rs");
}
